# Prawo cywilne (Kodeks cywilny). Każda pozycja: (pytanie, poprawna, [3 błędne], wyjaśnienie).
SEG = "CYW"
CAT = "plapCywilne"
Q = [
    ("Od kiedy człowiek ma zdolność prawną według Kodeksu cywilnego?",
     "Od chwili urodzenia", ["Od ukończenia 13 lat", "Od uzyskania pełnoletności", "Od chwili poczęcia"],
     "Art. 8 § 1 KC: każdy człowiek od chwili urodzenia ma zdolność prawną. Wiek 13 lat i pełnoletność decydują o zdolności do czynności prawnych, nie o zdolności prawnej."),
    ("Jaką zdolność do czynności prawnych ma czternastolatek, który nie jest ubezwłasnowolniony?",
     "Ograniczoną", ["Pełną", "Nie ma żadnej", "Częściową"],
     "Art. 15 KC: ograniczoną zdolność mają małoletni, którzy ukończyli 13 lat, oraz osoby ubezwłasnowolnione częściowo. Brak zdolności dotyczy dzieci poniżej 13 lat (art. 12 KC)."),
    ("Jaki skutek ma czynność prawna mająca na celu obejście ustawy?",
     "Jest nieważna", ["Jest wzruszalna", "Jest bezskuteczna względnie", "Jest ważna do czasu uchylenia"],
     "Art. 58 § 1 KC: czynność sprzeczna z ustawą albo mająca na celu jej obejście jest nieważna, chyba że właściwy przepis przewiduje inny skutek."),
    ("Kiedy przestaje wiązać oferta złożona przez telefon, jeśli nie oznaczono terminu odpowiedzi?",
     "Gdy nie zostanie przyjęta niezwłocznie", ["Po upływie doby od rozmowy", "Z końcem następnego dnia roboczego", "Po upływie tygodnia od złożenia"],
     "Art. 66 § 2 KC: oferta złożona w obecności drugiej strony albo za pomocą środka bezpośredniego porozumiewania się na odległość przestaje wiązać, gdy nie zostanie przyjęta niezwłocznie."),
    ("Strony zastrzegły formę pisemną bez rygoru nieważności i jej nie zachowały. Jaki jest co do zasady skutek w sporze?",
     "Ograniczenie dowodu ze świadków", ["Nieważność całej umowy", "Bezskuteczność wobec osób trzecich", "Obowiązek potwierdzenia u notariusza"],
     "Art. 76 w zw. z art. 74 § 1 KC: gdy strony zastrzegły formę bez określenia skutków, jest to forma dla celów dowodowych; jej niezachowanie wyłącza w sporze dowód ze świadków i z przesłuchania stron na fakt dokonania czynności, z wyjątkami z § 2. Nie dotyczy to stosunków między przedsiębiorcami (§ 4)."),
    ("Oświadczenie woli złożone w stanie wyłączającym świadome powzięcie decyzji jest:",
     "Bezwzględnie nieważne", ["Wzruszalne w ciągu roku", "Bezskuteczne do potwierdzenia", "Ważne, lecz zaskarżalne"],
     "Art. 82 KC: nieważne jest oświadczenie woli złożone przez osobę w stanie wyłączającym świadome albo swobodne powzięcie decyzji i wyrażenie woli. Roczny termin dotyczy uchylenia się od skutków błędu lub groźby (art. 88 KC)."),
    ("W jakim terminie wygasa uprawnienie do uchylenia się od skutków oświadczenia woli złożonego pod wpływem błędu?",
     "Rok od wykrycia błędu", ["2 lata od wykrycia błędu", "6 miesięcy od złożenia oświadczenia", "3 lata od złożenia oświadczenia"],
     "Art. 88 § 2 KC: uprawnienie wygasa w razie błędu z upływem roku od jego wykrycia. Uchylenie się następuje przez oświadczenie złożone drugiej stronie na piśmie (art. 88 § 1 KC)."),
    ("Kiedy groźba pozwala uchylić się od skutków złożonego oświadczenia woli?",
     "Gdy jest bezprawna i poważna", ["Tylko gdy pochodzi od drugiej strony", "Tylko gdy dotyczy życia", "Gdy wyrażono ją na piśmie"],
     "Art. 87 KC: groźba musi być bezprawna, a z okoliczności ma wynikać obawa poważnego niebezpieczeństwa osobistego lub majątkowego. Może pochodzić od drugiej strony lub od osoby trzeciej."),
    ("W jakiej formie należy udzielić pełnomocnictwa do sprzedaży nieruchomości?",
     "Aktu notarialnego", ["Pisemnej z podpisem poświadczonym", "Zwykłej pisemnej", "Dokumentowej"],
     "Art. 99 § 1 KC: gdy do ważności czynności potrzebna jest szczególna forma, pełnomocnictwo udziela się w tej samej formie. Umowa przenosząca własność nieruchomości wymaga aktu notarialnego (art. 158 KC)."),
    ("Co co do zasady dzieje się z umocowaniem pełnomocnika po śmierci mocodawcy?",
     "Wygasa", ["Przechodzi na spadkobierców", "Trwa do czasu odwołania", "Trwa do działu spadku"],
     "Art. 101 § 2 KC: umocowanie wygasa ze śmiercią mocodawcy lub pełnomocnika, chyba że w pełnomocnictwie inaczej zastrzeżono z przyczyn uzasadnionych treścią stosunku podstawowego."),
    ("Ile wynosi ogólny termin przedawnienia roszczeń majątkowych, jeśli przepis szczególny nie stanowi inaczej?",
     "6 lat", ["3 lata", "5 lat", "2 lata"],
     "Art. 118 KC: termin wynosi sześć lat, a dla roszczeń o świadczenia okresowe i związanych z działalnością gospodarczą trzy lata. Koniec terminu przypada na ostatni dzień roku kalendarzowego, chyba że termin jest krótszy niż dwa lata."),
    ("Co dzieje się po upływie terminu przedawnienia roszczenia przysługującego przeciwko konsumentowi?",
     "Nie można żądać jego zaspokojenia", ["Konsument musi podnieść zarzut", "Roszczenie wygasa dopiero po 10 latach", "Sąd zasądza je, gdy brak zarzutu"],
     "Art. 117 § 2¹ KC: po upływie terminu nie można domagać się zaspokojenia roszczenia przeciwko konsumentowi, więc sąd uwzględnia przedawnienie z urzędu. Wobec innych dłużników trzeba podnieść zarzut (art. 117 § 2 KC)."),
    ("Co przerywa bieg przedawnienia roszczenia?",
     "Uznanie roszczenia", ["Wezwanie do zapłaty", "Cesja wierzytelności", "Zmiana adresu dłużnika"],
     "Art. 123 § 1 pkt 2 KC: bieg przedawnienia przerywa uznanie roszczenia przez osobę, przeciwko której ono przysługuje. Samo przedsądowe wezwanie do zapłaty nie jest czynnością przed sądem ani uznaniem."),
    ("Po ilu latach samoistny posiadacz w dobrej wierze nabywa przez zasiedzenie własność nieruchomości?",
     "20 lat", ["30 lat", "25 lat", "40 lat"],
     "Art. 172 § 1 KC: posiadacz samoistny w dobrej wierze nabywa własność po 20 latach nieprzerwanego posiadania. Przy złej wierze potrzeba 30 lat (§ 2)."),
    ("Jak długo trzeba posiadać rzecz ruchomą jako posiadacz samoistny w dobrej wierze, by ją zasiedzieć?",
     "3 lata", ["2 lata", "5 lat", "10 lat"],
     "Art. 174 § 1 KC: zasiedzenie rzeczy ruchomej następuje po trzech latach posiadania samoistnego, chyba że posiadacz jest w złej wierze. W złej wierze rzeczy ruchomej nie można zasiedzieć."),
    ("Czego wymaga rozporządzenie rzeczą stanowiącą współwłasność?",
     "Zgody wszystkich współwłaścicieli", ["Zgody większości udziałów", "Zgody połowy współwłaścicieli", "Zgody współwłaściciela zarządcy"],
     "Art. 199 KC: do rozporządzania rzeczą wspólną i innych czynności przekraczających zwykły zarząd potrzebna jest zgoda wszystkich. Bez niej współwłaściciele mający co najmniej połowę udziałów mogą żądać rozstrzygnięcia przez sąd."),
    ("Jaki cel może mieć wyłącznie służebność gruntowa?",
     "Większą użyteczność gruntu władnącego", ["Zabezpieczenie wierzytelności właściciela", "Mieszkanie dla osoby bliskiej", "Pobieranie pożytków z cudzego gruntu"],
     "Art. 285 § 2 KC: służebność gruntowa może mieć jedynie na celu zwiększenie użyteczności nieruchomości władnącej lub jej oznaczonej części. Prawo mieszkania jest służebnością osobistą, a pobieranie pożytków to użytkowanie."),
    ("Za jakie następstwa zdarzenia odpowiada zobowiązany do odszkodowania?",
     "Za normalne następstwa", ["Za wszystkie następstwa", "Tylko za następstwa zawinione", "Za następstwa wskazane w umowie"],
     "Art. 361 § 1 KC: zobowiązany odpowiada tylko za normalne następstwa działania lub zaniechania, z którego szkoda wynikła (adekwatny związek przyczynowy). W tych granicach naprawienie obejmuje stratę i utracone korzyści (§ 2)."),
    ("Kto musi udowodnić, że postanowienie umowy z konsumentem uzgodniono indywidualnie?",
     "Ten, kto się na to powołuje", ["Zawsze konsument", "Rzecznik konsumentów", "Strona, która to kwestionuje"],
     "Art. 385¹ § 4 KC: ciężar dowodu, że postanowienie zostało uzgodnione indywidualnie, spoczywa na tym, kto się na to powołuje. Nie jest to strona kwestionująca uzgodnienie."),
    ("Kupujący dał zadatek, a sprzedawca nie wykonał umowy. Czego kupujący może żądać po odstąpieniu od umowy?",
     "Sumy dwukrotnie wyższej", ["Zwrotu zadatku z odsetkami", "Sumy trzykrotnie wyższej", "Kary umownej w wysokości ceny"],
     "Art. 394 § 1 KC: w razie niewykonania umowy przez drugą stronę można bez terminu dodatkowego odstąpić od umowy i, jeśli samemu dało się zadatek, żądać sumy dwukrotnie wyższej."),
    ("Na jakiej zasadzie odpowiada prowadzący przedsiębiorstwo wprawiane w ruch za pomocą sił przyrody?",
     "Ryzyka", ["Winy", "Słuszności", "Winy w nadzorze"],
     "Art. 435 § 1 KC przewiduje odpowiedzialność na zasadzie ryzyka: prowadzący zwalnia się tylko, gdy szkoda nastąpiła wskutek siły wyższej albo wyłącznie z winy poszkodowanego lub osoby trzeciej."),
    ("Szkoda wynikła ze zbrodni lub występku. W jakim terminie przedawnia się roszczenie o jej naprawienie?",
     "20 lat od popełnienia przestępstwa", ["3 lata od dowiedzenia się o szkodzie", "10 lat od zdarzenia szkodzącego", "6 lat od dnia wymagalności"],
     "Art. 442¹ § 2 KC: przy szkodzie z przestępstwa termin wynosi 20 lat od jego popełnienia, bez względu na to, kiedy poszkodowany dowiedział się o szkodzie. Trzy lata od dowiedzenia się to reguła ogólna z § 1."),
    ("Siedmiolatek wybił szybę sąsiada. Kto co do zasady odpowiada za szkodę?",
     "Zobowiązany do nadzoru nad dzieckiem", ["Dziecko ze swojego majątku", "Szkoła, do której dziecko chodzi", "Nikt, bo brak winy sprawcy"],
     "Art. 426 KC: małoletni poniżej 13 lat nie odpowiada za szkodę. Odpowiada osoba zobowiązana do nadzoru, chyba że wykaże, że uczyniła zadość obowiązkowi nadzoru (art. 427 KC)."),
    ("W jakim terminie od wydania nieruchomości musi zostać stwierdzona wada fizyczna, by sprzedawca odpowiadał z rękojmi?",
     "5 lat", ["2 lata", "3 lata", "4 lata"],
     "Art. 568 § 1 KC: sprzedawca odpowiada, jeżeli wada fizyczna zostanie stwierdzona przed upływem dwóch lat, a przy wadach nieruchomości przed upływem pięciu lat od wydania rzeczy."),
    ("Najem garażu zawarto na czas nieoznaczony, czynsz płatny jest miesięcznie, a umowa nie określa terminów wypowiedzenia. Jaki jest termin ustawowy?",
     "Miesiąc naprzód na koniec miesiąca", ["Trzy miesiące na koniec kwartału", "Dwa tygodnie naprzód", "Trzy dni naprzód"],
     "Art. 673 § 2 KC: gdy czynsz jest płatny miesięcznie, najem można wypowiedzieć na miesiąc naprzód na koniec miesiąca kalendarzowego. Trzy miesiące na koniec kwartału dotyczą czynszu płatnego rzadziej niż co miesiąc."),
    ("Jakiej formy wymaga umowa pożyczki o wartości 5000 zł?",
     "Dokumentowej", ["Pisemnej pod rygorem nieważności", "Aktu notarialnego", "Nie wymaga szczególnej formy"],
     "Art. 720 § 2 KC: umowa pożyczki o wartości ponad tysiąc złotych wymaga zachowania formy dokumentowej."),
    ("Spadkodawca pozostawił żonę i pięcioro dzieci. Jaka część spadku przypada żonie przy dziedziczeniu ustawowym?",
     "1/4", ["1/6", "1/2", "1/5"],
     "Art. 931 § 1 KC: dzieci i małżonek dziedziczą w częściach równych, ale część małżonka nie może być mniejsza niż jedna czwarta. Przy sześciu spadkobiercach równy udział wynosiłby 1/6, więc żona otrzymuje 1/4."),
    ("Spadkobierca nie złożył żadnego oświadczenia w ciągu sześciu miesięcy od dowiedzenia się o powołaniu. Jaki jest skutek?",
     "Przyjęcie z dobrodziejstwem inwentarza", ["Przyjęcie proste spadku", "Odrzucenie spadku", "Utrata prawa do zachowku"],
     "Art. 1015 § 2 KC: brak oświadczenia w terminie jest jednoznaczny z przyjęciem spadku z dobrodziejstwem inwentarza, czyli z ograniczeniem odpowiedzialności za długi (art. 1012 KC)."),
]
